// Verify Shopify's HMAC before trusting a single field.
//
// The raw body is required: re-serialising the parsed JSON changes whitespace
// and key order, the digest stops matching, and every legitimate order is
// rejected. That is why the webhook node above sets rawBody.
//
// timingSafeEqual, not ===, because a plain comparison returns early on the
// first differing byte and leaks the digest one character at a time.
const crypto = require('crypto');

const secret = $env.SHOPIFY_API_SECRET;
if (!secret) {
  throw new Error('SHOPIFY_API_SECRET is not set on this instance.');
}

const sent = $input.first().json.headers['x-shopify-hmac-sha256'];
const raw = $input.first().binary
  ? Buffer.from($input.first().binary.data.data, 'base64')
  : Buffer.from(JSON.stringify($input.first().json.body));

const expected = crypto.createHmac('sha256', secret).update(raw).digest('base64');

const a = Buffer.from(expected);
const b = Buffer.from(sent ?? '');
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('HMAC mismatch — request did not come from Shopify.');
}

const order = JSON.parse(raw.toString('utf8'));

// Flatten to exactly the columns the upsert writes. Shopify sends far more
// than this; carrying the rest through only makes the execution log harder to
// read during a demo.
return [{
  json: {
    shopify_order_id: String(order.id),
    order_number: order.name,
    email: order.email ?? null,
    phone: order.phone ?? order.customer?.phone ?? null,
    total: order.total_price,
    discount_total: order.total_discounts ?? '0.00',
    currency: order.currency,
    financial_status: order.financial_status,
    processed_at: order.processed_at,
    cancelled_at: order.cancelled_at ?? null,
    line_count: (order.line_items ?? []).length,
    unit_count: (order.line_items ?? []).reduce((n, li) => n + (li.quantity ?? 0), 0),
    product_titles: (order.line_items ?? []).map((li) => li.title)
  }
}];
